<?php
/** متابعة المنافسين: مواقعهم بتتقري كل يوم وأي تغيير في الأسعار أو الخدمات أو العروض بيتسجل */
$wid = (int)ws('id');
$AJ = !empty($_POST['ajax']);
$back = function (string $h = '') use (&$AJ, &$payload) { if ($AJ) { $m = $_SESSION['flash'] ?? null; unset($_SESSION['flash']); header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'flash' => $m, 'focus' => $h, 'd' => $payload()], JSON_UNESCAPED_UNICODE)); } redirect(url('competitors') . ($h !== '' ? '#' . $h : '')); };
$kinds = ['price_up' => t('رفع سعر'), 'price_down' => t('نزّل سعر'), 'price' => t('غيّر سعر'), 'offer_new' => t('عرض جديد'), 'offer_gone' => t('عرض خلص'), 'svc_new' => t('خدمة جديدة'),
    'svc_gone' => t('خدمة اتشالت'), 'hours' => t('المواعيد'), 'down' => t('الموقع وقع'), 'up' => t('الموقع رجع'), 'first' => t('أول قراءة'), 'soc_bio' => t('وصف الحساب'), 'soc_name' => t('اسم الحساب'), 'soc_link' => t('رابط الحساب'), 'ad_new' => t('إعلان جديد'), 'ad_stop' => t('أوقف إعلانًا'), 'page_new' => t('صفحة جديدة'), 'seo' => t('SEO'), 'tech_new' => t('أداة جديدة'), 'code_new' => t('كود خصم'), 'rating' => t('تغيّر التقييم'), 'rev_bad' => t('تقييم سلبي')];
$host = function ($u) { return preg_replace('/^www\./', '', (string)parse_url($u, PHP_URL_HOST)); };
/** كل بيانات الصفحة في JSON واحد (الكروت، التغييرات، المقارنة، الأرقام) */
$payload = function () use ($host) {
    $comps = comp_list(); $events = comp_events(null, 300); $others = array_values(array_filter($comps, function ($x) { return empty($x['is_self']); })); $prices = $others ? comp_price_table($others) : []; $since = strtotime('-30 days');
    $ago = function ($d) { if (!$d) return ''; $s = time() - strtotime($d); return $s < 3600 ? t('من %s دقيقة', max(1, (int)($s / 60))) : ($s < 86400 ? t('من %s ساعة', (int)($s / 3600)) : t('من %s يوم', (int)($s / 86400))); };
    $C = []; foreach ($comps as $c) { $sn = json_decode((string)$c['snap'], true) ?: [];
        $C[] = ['id' => (int)$c['id'], 'name' => (string)$c['name'], 'url' => (string)$c['url'], 'host' => $host($c['url']), 'note' => (string)$c['note'], 'links' => array_values(array_filter(explode("\n", (string)$c['links']))),
            'checked' => $c['last_check'] ? fmt_date($c['last_check'], 'd/m h:i A') : '', 'err' => (string)($sn['err'] ?? ''), 'ago' => $ago($c['last_check']), 'ok' => (int)$c['last_ok'],
            'services' => array_values(array_map(function ($x) { return ['name' => (string)$x['name'], 'price' => (string)$x['price']]; }, (array)($sn['services'] ?? []))), 'offers' => array_values((array)($sn['offers'] ?? [])), 'soc' => cs_card((int)$c['id']), 'self' => (int)!empty($c['is_self']), 'lastDays' => (function ($c) { $m = cmp_metrics($c); return $m['lastDays']; })($c), 'ads' => (int)db()->query('SELECT COUNT(*) FROM competitor_ads WHERE active = 1 AND competitor_id = ' . (int)$c['id'])->fetchColumn(),
            'rate' => (function ($id) { $r = db()->query('SELECT SUM(rating * reviews_count) / NULLIF(SUM(reviews_count), 0) a, SUM(reviews_count) n, COUNT(*) b FROM competitor_places WHERE rating IS NOT NULL AND competitor_id = ' . (int)$id)->fetch(); return $r && $r['a'] !== null ? ['avg' => round((float)$r['a'], 1), 'n' => (int)$r['n'], 'b' => (int)$r['b']] : null; })($c['id'])]; }
    $E = array_map(function ($e) use ($since) { return ['cid' => (int)$e['competitor_id'], 'cname' => (string)$e['cname'], 'kind' => (string)$e['kind'], 'title' => comp_ev_title($e['kind'], (string)$e['title']), 'detail' => comp_ev_detail($e['kind'], $e['detail']),
        'day' => substr((string)$e['created_at'], 0, 10), 'date' => fmt_date($e['created_at'], 'd/m'), 'recent' => strtotime($e['created_at']) >= $since ? 1 : 0]; }, $events);
    $P = []; $cheaper = 0;
    foreach ($prices as $r) { $mn = comp_price_num((string)$r['mine']); $th = [];
        foreach ((array)($r['them'] ?? []) as $cid => $h) { if (!is_array($h)) continue; $n = comp_price_num((string)$h['price']); $th[(string)$cid] = ['price' => (string)$h['price'], 'n' => $n, 'd' => ($mn && $n !== null) ? (int)round(($n - $mn) / $mn * 100) : null]; if ($mn && $n !== null && $n < $mn) $cheaper++; }
        $P[] = ['name' => (string)$r['name'], 'mine' => (string)$r['mine'], 'mn' => $mn, 'them' => (object)$th]; }
    $rec = array_filter($E, function ($e) { return $e['recent'] && $e['kind'] !== 'first'; });
    return ['comps' => $C, 'events' => array_values(array_filter($E, function ($e) { return $e['kind'] !== 'first'; })), 'prices' => $P, 'saved' => cmp_saved_ids(),
        'k' => ['n' => count($C), 'changes' => count($rec), 'up' => count(array_filter($rec, function ($e) { return $e['kind'] === 'price_up'; })), 'down' => count(array_filter($rec, function ($e) { return $e['kind'] === 'price_down'; })), 'cheaper' => $cheaper]];
};
if (($_GET['export'] ?? '') === 'csv') { header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="competitors-' . date('Y-m-d') . '.csv"'); echo cmp_csv(); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $GLOBALS['cw_no_psi'] = true; // PageSpeed بطيء (لحد دقيقة): بيتعمل من التشغيل الدوري بس
    $a = (string)($_POST['action'] ?? '');
    if ($a === 'overview') { header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'o' => cmp_overview()], JSON_UNESCAPED_UNICODE)); }
    if ($a === 'self_add') { cmp_self_create(); $sf = cmp_self(); if ($sf) { try { cs_sync($sf); if (cs_on()) { cs_refresh($sf); ca_refresh($sf); } comp_check($sf); } catch (Throwable $e) {} } flash('success', t('أضفنا حساباتك للمقارنة. البيانات تكتمل خلال دقائق.')); $back(); }
    if ($a === 'rules_save') { $cur = cmp_rules(); $in = json_decode((string)($_POST['rules'] ?? ''), true) ?: [];
        foreach ($cur as $k => $v) foreach ($v as $f => $x) if (isset($in[$k][$f])) $cur[$k][$f] = $f === 'on' ? ((int)!empty($in[$k][$f])) : max(0, min(1000, (float)$in[$k][$f]));
        save_setting('cmp_rules_' . $wid, json_encode($cur)); header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'rules' => cmp_rules()])); }
    if ($a === 'save_toggle') { $on = cmp_save_toggle((string)($_POST['kind'] ?? '') === 'ad' ? 'ad' : 'post', (int)($_POST['ref'] ?? 0)); header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'on' => $on, 'ids' => cmp_saved_ids()])); }
    if ($a === 'saved_note') { db()->prepare('UPDATE competitor_saved SET note = ? WHERE id = ? AND workspace_id = ?')->execute([mb_substr(trim((string)($_POST['note'] ?? '')), 0, 500) ?: null, (int)($_POST['sid'] ?? 0), $wid]); header('Content-Type: application/json; charset=utf-8'); exit('{"ok":true}'); }
    if ($a === 'saved_del') { db()->prepare('DELETE FROM competitor_saved WHERE id = ? AND workspace_id = ?')->execute([(int)($_POST['sid'] ?? 0), $wid]); header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'o' => cmp_overview()], JSON_UNESCAPED_UNICODE)); }
    if ($a === 'disc_start') { header('Content-Type: application/json; charset=utf-8'); if (!cs_on()) exit(json_encode(['ok' => false, 'error' => t('اربط Apify من صفحة التكاملات أولًا.')]));
        $q = trim((string)($_POST['q'] ?? '')); if ($q === '' && cmp_disc_query() === '') exit(json_encode(['ok' => false, 'error' => t('اكتب نوع النشاط والمدينة، مثل: صالون نسائي الرياض')]));
        try { cmp_disc_start($q); } catch (Throwable $e) { exit(json_encode(['ok' => false, 'error' => $e->getMessage()])); } exit(json_encode(['ok' => true, 'o' => cmp_overview()], JSON_UNESCAPED_UNICODE)); }
    if ($a === 'disc_poll') { if (cmp_disc_pending()) { try { cmp_disc_collect(); } catch (Throwable $e) {} } header('Content-Type: application/json; charset=utf-8'); exit(json_encode(['ok' => true, 'o' => cmp_overview()], JSON_UNESCAPED_UNICODE)); }
    if ($a === 'digest_now') { $ok = cmp_digest_tick(true); flash($ok ? 'success' : 'error', $ok ? t('أرسلنا الملخص الأسبوعي إلى بريد المديرين ✓') : t('لا يوجد ما يُرسل، أو تعذّر الإرسال. راجع إعدادات البريد.')); $back(); }
    if ($a === 'kw_save') {
        $kw = array_values(array_unique(array_filter(array_map(function ($x) { return mb_substr(trim($x), 0, 80); }, preg_split('/[\n,،]+/u', (string)($_POST['kw'] ?? ''))))));
        save_setting('comp_kw_' . $wid, json_encode(array_slice($kw, 0, 10), JSON_UNESCAPED_UNICODE));
        $started = false; if ($kw && cs_on()) { try { $started = cw_rank_start($wid); } catch (Throwable $e) {} }
        $c0 = comp_get((int)($_POST['id'] ?? 0)); header('Content-Type: application/json; charset=utf-8');
        exit(json_encode(['ok' => true, 'started' => $started, 'r' => $c0 ? cw_report($c0) : null], JSON_UNESCAPED_UNICODE));
    }
    if ($a === 'add') {
        $name = mb_substr(trim((string)($_POST['name'] ?? '')), 0, 120);
        $u = trim((string)($_POST['url'] ?? '')); if ($u !== '' && !preg_match('~^https?://~i', $u)) $u = 'https://' . $u;
        if ($name === '' || !filter_var($u, FILTER_VALIDATE_URL) || !preg_match('~^https?://~i', $u)) { flash('error', t('اكتب اسم المنافس ورابط موقعه.')); $back(); }
        if (count(array_filter(comp_list(), function ($x) { return empty($x['is_self']); })) >= 15) { flash('error', t('الحد الأقصى 15 منافس.')); $back(); }
        $links = implode("\n", array_slice(array_values(array_filter(array_map('trim', preg_split('/\s+/', (string)($_POST['links'] ?? ''))), function ($x) { return preg_match('~^https?://~i', $x); })), 0, 6));
        db()->prepare('INSERT INTO competitors (workspace_id, name, url, links, note) VALUES (?, ?, ?, ?, ?)')->execute([$wid, $name, mb_substr($u, 0, 500), $links ?: null, mb_substr(trim((string)($_POST['note'] ?? '')), 0, 500) ?: null]);
        $c = comp_get((int)db()->lastInsertId());
        comp_check($c); $c = comp_get((int)$c['id']);
        try { cs_sync($c); if (cs_on()) { cs_refresh($c); ca_refresh($c); cg_start($c, 'find'); } } catch (Throwable $e) {}
        log_activity('competitor.add', $name);
        if ($c['last_ok']) flash('success', t('اتضاف %s واتقرا موقعه ✓', $name)); else flash('error', t('اتضاف %s، بس موقعه مش بيفتح دلوقتي. هنحاول تاني بكرة.', $name));
        $back('c' . (int)$c['id']);
    }
    $c = comp_get((int)($_POST['id'] ?? 0));
    if (!$c) { flash('error', t('المنافس ده مش موجود.')); $back(); }
    // السوشيال: كل البيانات بتتجاب عند فتح التبويب بس
    $SJ = function ($d) { header('Content-Type: application/json; charset=utf-8'); exit(json_encode($d, JSON_UNESCAPED_UNICODE)); };
    if ($a === 'reviews') $SJ(['ok' => true, 'r' => cg_report($c)]);
