    }
    if ($a === 'del') {
        cs_forget_comp((int)$c['id']); foreach (['ca_run_', 'ca_err_', 'ca_empty_', 'cg_run_', 'cg_err_', 'cg_found_'] as $k) { try { db()->prepare('DELETE FROM settings WHERE name = ?')->execute([$k . (int)$c['id']]); } catch (Throwable $e) {} }
        db()->prepare('DELETE FROM competitors WHERE id = ? AND workspace_id = ?')->execute([(int)$c['id'], $wid]);
